#!/usr/bin/env python3
"""Generate the compact static index used by the Reference explorer.

Entries contain metadata only:
    [title, route, category_index, aliases, parent]

Categories come directly from the top-level Reference navigation. Explicit
level-two anchors inside autogenerated documentation blocks are included as
entity links; document bodies are never added to the client-side index.
Functions and settings use surface-specific generated metadata to identify
entity anchors on pages that document multiple entities.
"""

import json
import re
from pathlib import Path
from typing import Any


ENTITY_SECTION_MARKERS = {
    'Functions': re.compile(r'^\s*Introduced in:', re.MULTILINE),
    'Settings': re.compile(r'<SettingsInfoBlock\b'),
}


def unquote_scalar(value: str) -> str:
    value = value.strip()
    if len(value) >= 2 and value[0] == "'" and value[-1] == "'":
        return value[1:-1].replace("''", "'")
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        return re.sub(r'\\(["\\])', r'\1', value[1:-1])
    return value


def parse_frontmatter(content: str) -> dict[str, Any]:
    match = re.match(r'^---\s*\n(.*?)\n---\s*\n', content, re.DOTALL)
    if not match:
        return {}

    raw_fields: dict[str, str] = {}
    current_key = ''
    for raw_line in match.group(1).splitlines():
        if raw_line[:1].isspace() and current_key:
            raw_fields[current_key] += ' ' + raw_line.strip()
            continue
        line = raw_line.strip()
        if not line or line.startswith('#') or ':' not in line:
            continue
        current_key, value = line.split(':', 1)
        current_key = current_key.strip()
        raw_fields[current_key] = value.strip()

    frontmatter: dict[str, Any] = {}
    for key, value in raw_fields.items():
        if value.startswith('[') and value.endswith(']'):
            items = [unquote_scalar(item) for item in value[1:-1].split(',')]
            frontmatter[key] = [item for item in items if item]
        else:
            frontmatter[key] = unquote_scalar(value)
    return frontmatter


def route_for(page: str) -> str:
    route = '/' + page
    return route[:-6] if route.endswith('/index') else route


def plain_text(value: str) -> str:
    value = re.sub(r'\[([^]]+)\]\([^)]+\)', r'\1', value)
    value = re.sub(r'<[^>]+>', '', value)
    value = value.replace('`', '').replace('*', '')
    return re.sub(r'\s+', ' ', value).strip()


def autogenerated_entities(content: str, category: str) -> list[tuple[str, str]]:
    """Return structured entities from generated documentation blocks.

    Functions are identified by generated version metadata and settings by the
    generated SettingsInfoBlock component. Other surfaces use page-level
    navigation and frontmatter rather than blanket anchor extraction.
    """
    entities: list[tuple[str, str]] = []
    blocks = re.findall(
        r'\{/\*AUTOGENERATED_START\*/\}(.*?)\{/\*AUTOGENERATED_END\*/\}',
        content,
        re.DOTALL,
    )
    marker = ENTITY_SECTION_MARKERS.get(category)
    if not marker:
        return entities

    for block in blocks:
        headings = list(re.finditer(
            r'^##\s+(.+?)\s+\{#([^}]+)\}\s*$',
            block,
            re.MULTILINE,
        ))
        for index, match in enumerate(headings):
            end = headings[index + 1].start() if index + 1 < len(headings) else len(block)
            if not marker.search(block[match.end():end]):
                continue
            heading, anchor = match.groups()
            title = plain_text(heading)
            if title and anchor:
                entities.append((title, anchor))
    return entities


def aliases_for(page: str, title: str, frontmatter: dict[str, Any]) -> list[str]:
    candidates: list[str] = []
    sidebar_title = frontmatter.get('sidebarTitle', '')
    if isinstance(sidebar_title, str):
        candidates.append(sidebar_title)

    keywords = frontmatter.get('keywords', [])
    if isinstance(keywords, str):
        keywords = [keywords]
    candidates.extend(keyword for keyword in keywords if isinstance(keyword, str))

    basename = page.rsplit('/', 1)[-1]
    if basename != 'index':
        candidates.append(basename)

    aliases = []
    seen = {title.casefold()}
    for candidate in candidates:
        candidate = candidate.strip()
        normalized = candidate.casefold()
        if candidate and normalized not in seen:
            aliases.append(candidate)
            seen.add(normalized)
    return aliases


def collect_pages(
    items: list[Any],
    category: str,
    trail: list[str],
    navigation_dir: Path,
) -> list[dict[str, Any]]:
    pages: list[dict[str, Any]] = []
    for item in items:
        if isinstance(item, str):
            pages.append({'page': item, 'category': category, 'trail': trail})
            continue
        if not isinstance(item, dict):
            continue

        if '$ref' in item:
            referenced_path = (navigation_dir / item['$ref']).resolve()
            referenced = json.loads(referenced_path.read_text(encoding='utf-8'))
            group = referenced.get('group', '')
            pages.extend(collect_pages(
                referenced.get('pages', []),
                category,
                [*trail, group] if group else trail,
                referenced_path.parent,
            ))
            continue

        group = item.get('group', '')
        pages.extend(collect_pages(
            item.get('pages', []),
            category,
            [*trail, group] if group else trail,
            navigation_dir,
        ))
    return pages


def first_page(items: list[Any]) -> str:
    """Return the first page in a navigation branch."""
    for item in items:
        if isinstance(item, str):
            return item
        if isinstance(item, dict) and '$ref' not in item:
            page = first_page(item.get('pages', []))
            if page:
                return page
    return ''


def main() -> int:
    docs_root = Path(__file__).resolve().parents[2]
    navigation = json.loads((docs_root / 'reference' / 'navigation.json').read_text(encoding='utf-8'))

    page_records: list[dict[str, Any]] = []
    category_routes: dict[str, str] = {}
    for item in navigation['pages']:
        if not isinstance(item, dict):
            continue
        category = item.get('group', 'Reference')
        overview_page = first_page(item.get('pages', []))
        if overview_page:
            category_routes[category] = route_for(overview_page)
        page_records.extend(collect_pages(
            item.get('pages', []),
            category,
            [],
            docs_root / 'reference',
        ))

    entries = []
    skipped = []
    for record in page_records:
        page = record['page']
        file_path = docs_root / f'{page}.mdx'
        if not file_path.exists():
            skipped.append(page)
            continue

        content = file_path.read_text(encoding='utf-8')
        frontmatter = parse_frontmatter(content)
        title = frontmatter.get('title') or frontmatter.get('sidebarTitle')
        if not isinstance(title, str) or not title:
            skipped.append(page)
            continue

        page_aliases = aliases_for(page, title, frontmatter)
        entries.append({
            'title': title,
            'href': route_for(page),
            'category': record['category'],
            'aliases': page_aliases,
            'trail': record['trail'],
        })

        if record['category'] in ENTITY_SECTION_MARKERS:
            page_names = {name.casefold() for name in [title, *page_aliases]}
            for anchor_title, anchor in autogenerated_entities(content, record['category']):
                if anchor_title.casefold() in page_names:
                    continue
                entries.append({
                    'title': anchor_title,
                    'href': f'{route_for(page)}#{anchor}',
                    'category': record['category'],
                    'aliases': [],
                    'trail': [*record['trail'], title],
                })

    entries.sort(key=lambda entry: entry['title'].casefold())
    populated_categories = {entry['category'] for entry in entries}
    category_names = [
        category_name
        for category_name in category_routes
        if category_name in populated_categories
    ]
    categories = [
        {
            'name': category_name,
            'count': sum(1 for entry in entries if entry['category'] == category_name),
            'href': category_routes.get(category_name, ''),
        }
        for category_name in category_names
    ]
    category_indexes = {name: index for index, name in enumerate(category_names)}

    compact_entries = [
        [
            entry['title'],
            entry['href'],
            category_indexes[entry['category']],
            entry['aliases'],
            entry['trail'][-1] if entry['trail'] else '',
        ]
        for entry in entries
    ]
    index = {'categories': categories, 'entries': compact_entries}
    output_path = docs_root / 'snippets' / 'components' / 'ReferenceExplorer' / 'reference-data.jsx'
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(
        '// AUTO-GENERATED by _site/scripts/update_reference_index.py — do not edit by hand.\n'
        '// Entry schema: [title, route, category_index, aliases, parent].\n'
        f'export const referenceIndex = {json.dumps(index, separators=(",", ":"), ensure_ascii=False)};\n',
        encoding='utf-8',
    )

    print(f'Wrote {len(entries)} Reference entries across {len(categories)} navigation categories')
    if skipped:
        print(f'Skipped {len(skipped)} navigation entries without a matching titled MDX file')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
